package com.oyuki.marketsquare.entity; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="local_governments") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class LocalGovernment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="state_id") private State state; @Column(nullable=false,length=120) private String name; @Column(nullable=false) @Builder.Default private boolean active=true; }